mkdir -p /app/bin /app/out; cat > /app/bin/hourly.py <<'EOF'
import sys, os, re, json, math
from datetime import datetime, timezone
from collections import defaultdict

QS = ["temp", "rh", "pres", "wspd", "wdir", "rain"]
RANGE = {"temp": (-50, 60), "rh": (0, 100), "pres": (870, 1085),
         "wspd": (0, 60), "wdir": (0, 360), "rain": (0, 5000)}
CANON = {"temp": "degC", "rh": "pct", "pres": "hPa", "wspd": "ms", "wdir": "deg", "rain": "mm"}


def conv(q, unit, v):
    if q == "temp":
        if unit == "degF": return (v - 32) * 5 / 9
        if unit == "K": return v - 273.15
    elif q == "rh":
        if unit == "frac": return v * 100
    elif q == "pres":
        if unit == "kPa": return v * 10
        if unit == "inHg": return v * 33.8638866667
        if unit == "mmHg": return v * 1.33322387415
    elif q == "wspd":
        if unit == "kmh": return v / 3.6
        if unit == "kn": return v * 1852 / 3600
        if unit == "mph": return v * 0.44704
    elif q == "rain":
        if unit.startswith("tips:"): return v * float(unit[5:])
    return v


def epoch(s):
    s = s.strip().replace("T", " ")
    d = datetime.strptime(s, "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    return int(d.timestamp())


def parse_tz(s):
    s = s.strip()
    if s == "Z": return 0
    sign = -1 if s[0] == "-" else 1
    h, m = s[1:].split(":")
    return sign * (int(h) * 3600 + int(m) * 60)


def is_missing(f):
    f = f.strip()
    if f == "" or f == "---" or f.lower() == "nan": return True
    if re.fullmatch(r"-9999(\.0*)?", f): return True
    return False


DIR = re.compile(r"#\s*([a-z]+)\s*:(.*)$")


def read_file(path):
    with open(path, "rb") as fh:
        text = fh.read().decode("utf-8-sig")
    hdr = {}
    cols = None
    units = {q: CANON[q] for q in QS}
    rows = []   # (logger_utc, {q: value})
    syncs = []  # (logger_utc, ref)
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if not line.strip(): continue
        if line[0] == "#":
            m = DIR.match(line)
            if not m: continue
            k, v = m.group(1), m.group(2).strip()
            if k in ("station", "upload", "interval", "tz"):
                hdr.setdefault(k, v)
            elif k == "columns":
                cols = [c.strip() for c in v.split(",")]
            elif k == "units":
                for p in v.split():
                    if "=" in p:
                        q, u = p.split("=", 1)
                        units[q] = u
            elif k == "sync":
                d = {}
                for p in v.split():
                    if "=" in p:
                        a, b = p.split("=", 1)
                        d[a] = b
                if "logger" in d and "ref" in d:
                    tz = parse_tz(hdr["tz"])
                    syncs.append((epoch(d["logger"]) - tz,
                                  epoch(d["ref"].rstrip("Z"))))
            continue
        f = [x.strip() for x in line.split(",")]
        tz = parse_tz(hdr["tz"])
        t = epoch(f[0]) - tz
        vals = {}
        for c, x in zip(cols, f):
            if c == "time" or c not in RANGE: continue
            if is_missing(x): continue
            try:
                v = conv(c, units[c], float(x))
            except ValueError:
                continue
            lo, hi = RANGE[c]
            if v != v or v < lo or v > hi: continue
            vals[c] = v
        rows.append((t, vals))
    return hdr, rows, syncs


def main(indir, outfile):
    st = {}
    for name in sorted(os.listdir(indir)):
        p = os.path.join(indir, name)
        if not name.endswith(".log") or not os.path.isfile(p): continue
        hdr, rows, syncs = read_file(p)
        if "station" not in hdr: continue
        s = st.setdefault(hdr["station"], {"interval": None, "rows": {}, "syncs": {}})
        up = int(hdr["upload"])
        if "interval" in hdr: s["interval"] = int(float(hdr["interval"]))
        for t, vals in rows:
            old = s["rows"].get(t)
            if old is None or old[0] < up: s["rows"][t] = (up, vals)
        for t, ref in syncs:
            old = s["syncs"].get(t)
            if old is None or old[0] < up: s["syncs"][t] = (up, ref)
    out = []
    for sid in sorted(st):
        s = st[sid]
        if not s["rows"]: continue
        iv = s["interval"]
        sp = sorted((t, ref - t) for t, (u, ref) in s["syncs"].items())

        def offset(t):
            if not sp: return 0
            if t <= sp[0][0]: return sp[0][1]
            if t >= sp[-1][0]: return sp[-1][1]
            lo, hi = 0, len(sp) - 1
            while hi - lo > 1:
                mid = (lo + hi) // 2
                if sp[mid][0] <= t: lo = mid
                else: hi = mid
            t1, o1 = sp[lo]; t2, o2 = sp[hi]
            return (o1 * (t2 - t1) + (o2 - o1) * (t - t1)) // (t2 - t1)

        recs = []
        for t, (u, vals) in s["rows"].items():
            recs.append((t + offset(t), vals))
        recs.sort(key=lambda r: r[0])
        hour_of = lambda c: -((-c) // 3600)
        byh = defaultdict(list)
        for c, vals in recs: byh[hour_of(c)].append((c, vals))
        # rain increments
        inc = {}
        prev = None
        for i, (c, vals) in enumerate(recs):
            if "rain" in vals:
                r = vals["rain"]
                if prev is not None and (c - prev[0]) * 2 <= 5 * iv:
                    inc[i] = r - prev[1] if r >= prev[1] else r
                prev = (c, r)
        idx_hour = {}
        for i, (c, vals) in enumerate(recs): idx_hour[i] = hour_of(c)
        rain_sum = defaultdict(float)
        for i, d in inc.items(): rain_sum[idx_hour[i]] += d
        expected = 3600 // iv
        h0, h1 = hour_of(recs[0][0]), hour_of(recs[-1][0])
        hours = []
        for h in range(h0, h1 + 1):
            rs = byh.get(h, [])
            e = {"hour": datetime.fromtimestamp(h * 3600, timezone.utc).strftime("%Y-%m-%dT%H:00:00Z")}
            for q in QS:
                vs = [v[q] for c, v in rs if q in v]
                n = len(vs)
                ok = n * 4 >= expected * 3 and n > 0
                val = None
                if ok:
                    if q in ("temp", "rh", "pres", "wspd"):
                        val = math.fsum(vs) / n
                    elif q == "wdir":
                        sx = sy = 0.0; k = 0
                        for c, v in rs:
                            if "wdir" in v and v.get("wspd", 0) > 0 and "wspd" in v:
                                a = math.radians(v["wdir"])
                                sx += math.sin(a); sy += math.cos(a); k += 1
                        if k and (abs(sx) > 1e-12 or abs(sy) > 1e-12):
                            val = math.degrees(math.atan2(sx, sy)) % 360
                    else:
                        val = rain_sum.get(h, 0.0)
                if val is not None:
                    val = round(val, 2)
                    if val >= 360 or val == 0: val = 0.0 if q == "wdir" or val == 0 else val
                e[q] = {"value": val, "n": n}
            hours.append(e)
        out.append({"station": sid, "interval_s": iv, "hours": hours})
    with open(outfile, "w") as f:
        json.dump({"stations": out}, f)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
